import{c as t,Q as r,j as a,m as o}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Multi-Layered Memory Architectures for LLM Agents: An Experimental Evaluation of Long-Term Context Retention","description":"","frontmatter":{"url":"https://arxiv.org/abs/2603.29194","title":"Multi-Layered Memory Architectures for LLM Agents: An Experimental Evaluation of Long-Term Context Retention","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2603.29194,"authors":["Sunil Tiwari","Payal Fofadiya"],"domains":["cs.CV"],"html":"https://arxiv.org/html/2603.29194v1","pdf_path":"pdfs/2603.29194.pdf","published_date":"2026-03-31T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-03-31-multi-layered-memory-architectures-llm-agents-2603-29194.md","filePath":"research/papers/2026-03-31-multi-layered-memory-architectures-llm-agents-2603-29194.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-03-31-multi-layered-memory-architectures-llm-agents-2603-29194.md"};function n(s,e,l,c,d,m){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="multi-layered-memory-architectures-for-llm-agents-an-experimental-evaluation-of-long-term-context-retention" tabindex="-1">Multi-Layered Memory Architectures for LLM Agents: An Experimental Evaluation of Long-Term Context Retention <a class="header-anchor" href="#multi-layered-memory-architectures-for-llm-agents-an-experimental-evaluation-of-long-term-context-retention" aria-label="Permalink to &quot;Multi-Layered Memory Architectures for LLM Agents: An Experimental Evaluation of Long-Term Context Retention&quot;">​</a></h1><p><strong>Authors</strong>: Sunil Tiwari, Payal Fofadiya <strong>Published</strong>: March 31, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2603.29194" target="_blank" rel="noreferrer">https://arxiv.org/abs/2603.29194</a> · <a href="https://arxiv.org/html/2603.29194v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2603.29194 <strong>Categories</strong>: cs.CV <strong>PDF</strong>: <a href="https://arxiv.org/abs/2603.29194" target="_blank" rel="noreferrer">research/papers/pdfs/2603.29194.pdf</a> (8 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Long-horizon dialogue systems suffer from semantic drift and unstable memory retention across extended sessions. This paper presents a Multi-Layer Memory Framework that decomposes dialogue history into working, episodic, and semantic layers with adaptive retrieval gating and retention regularization. The architecture controls cross-session drift while maintaining bounded context growth and computational efficiency. Experiments on LOCOMO, LOCCO, and LoCoMo show improved performance, achieving 46.85 Success Rate, 0.618 overall F1 with 0.594 multi-hop F1, and 56.90% six-period retention while reducing false memory rate to 5.1% and context usage to 58.40%. Results confirm enhanced long-term retention and reasoning stability under constrained context budgets.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 Multi-Layer Memory Framework：將對話歷史拆為 working / episodic / semantic 三層，搭配 adaptive retrieval gating 與 retention regularization。</li><li>在控制 cross-session drift 的同時維持 bounded context growth 與計算效率。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>於 LOCOMO / LOCCO / LoCoMo：Success Rate 46.85、overall F1 0.618、multi-hop F1 0.594、six-period retention 56.90%。</li><li>false memory rate 降至 5.1%，context usage 降至 58.40%。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>文件未於 abstract 列明確 limitation；判斷弱點：2 作者短篇（8 頁），benchmark 名稱（LOCOMO/LOCCO/LoCoMo）疑有重複，需正文確認；retention 56.90% 仍偏低。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>「bounded context growth + context usage 降至 58.40%」直接對應 context-management 的 token budget 與 compact 觸發閾值。</li><li>working/episodic/semantic 三層對應本批 LightMem 的 STM/MTM/LTM；可作為理解本庫 MEMORY（語意層）vs handoff/progress（情節層）vs 即時對話（working）的概念框架。</li><li>「false memory rate 5.1%」呼應 core.md TEST「Fail Loud」與 RECORD——記憶系統須可觀測退化（false memory 即一種退化訊號）。</li></ul>',16)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
